import {seed,newSession,original,revised,concise,fileList} from './data.js';
const $=q=>document.querySelector(q);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='kimi-paper-design-v2.1';let db;try{db=JSON.parse(localStorage.getItem(key))}catch{}if(!db?.projects?.length)db=seed();
const ui={doc:'preview',file:'main.tex',proposal:'p1',autoTranslate:true,busy:false,selection:'',queued:[],history:null};
if(!db.projects.some(p=>p.id===db.active))db.active=db.projects[0].id;
ui.proposal=db.projects.find(p=>p.id===db.active).proposals.at(-1)?.id;
const project=()=>db.projects.find(p=>p.id===db.active);const session=()=>project().sessions.find(s=>s.id===project().session);const proposal=()=>project().proposals.find(p=>p.id===ui.proposal);
const paths={folder:'M3 6h6l2 2h10v12H3z',file:'M6 3h8l4 4v14H6z M14 3v5h5',chat:'M4 4h16v12H9l-5 4z',plus:'M12 4v16M4 12h16',arrow:'M12 19V5M6 11l6-6 6 6',chevron:'M7 10l5 5 5-5',panel:'M3 4h18v16H3zM9 4v16',attach:'M8 13l6-6a3 3 0 014 4l-8 8a5 5 0 01-7-7l9-9',expand:'M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`}
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch{toast('浏览器无法保存样稿状态，刷新可能丢失演示操作')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function modal(html,wide=false){$('#selection-popup').hidden=true;$('#dialog').classList.toggle('wide',wide);$('#modal').innerHTML=html;$('#dialog').showModal()}
function close(){ $('#dialog').close() }
function sidebar(){const p=project();$('#project-switch').innerHTML=icon('folder')+esc(p.name)+icon('chevron');$('#project-switch').title=p.path;$('#sidebar').innerHTML=`<section><h2>项目文件</h2>${p.files.length?p.files.map(f=>`${f.includes('/')?`<div class="folder">${icon('folder')}${f.split('/')[0]}</div>`:''}<button class="file ${f.includes('/')?'child':''} ${ui.file===f?'active':''}" data-file="${esc(f)}">${icon('file')}${esc(f.split('/').at(-1))}</button>`).join(''):'<p class="mini" style="padding:8px">还没有文件<br>从左侧对话开始起草</p>'}</section><section class="sessions"><h2>会话</h2>${p.sessions.filter(s=>!s.archived).map(s=>`<button class="session ${s.id===p.session?'active':''}" data-session="${s.id}">${icon('chat')}${esc(s.title)}</button>`).join('')}<details><summary>已归档 ${p.sessions.filter(s=>s.archived).length}</summary>${p.sessions.filter(s=>s.archived).map(s=>`<button class="session" data-session="${s.id}">${icon('chat')}${esc(s.title)}</button>`).join('')}</details><button class="new-session" data-action="newsession">${icon('plus')}新建会话</button><div class="path">${esc(p.path)}<br>main · 示例项目</div></section>`}
function renderMessages(){const s=session(),p=project();$('#chat-heading').innerHTML=`<div><h1>${esc(s.title)}</h1><p class="sub">${s.archived?'已归档 · 可继续查看':'当前项目的持续会话'} · <button data-action="context">上下文</button></p></div><button class="icon" data-action="archivesession" aria-label="${s.archived?'恢复会话':'归档会话'}">${icon(s.archived?'plus':'folder')}</button>`;$('#messages').innerHTML=s.messages.length?s.messages.map(m=>{const pr=p.proposals.find(v=>v.id===m.proposal);return `<article class="message"><div class="who"><span class="avatar ${m.role==='user'?'user':''}">${m.role==='user'?'你':'K'}</span>${m.role==='user'?'你':'Kimi'}</div>${(m.quotes||[]).map(q=>`<blockquote>${esc(q)}</blockquote>`).join('')}<p>${esc(m.text)}</p>${m.artifact?`<button class="artifact" data-action="showpaper">${icon('file')}${esc(m.artifact)}</button>`:''}${pr?`<div class="proposal-row"><span>${esc(pr.title)} · ${pr.status==='adopted'?'已采纳':pr.status==='archived'?'已归档':'待确认'}</span><div class="actions"><button data-preview="${pr.id}">查看效果</button><button class="primary" data-adopt="${pr.id}" ${pr.status!=='pending'?'disabled':''}>采纳</button><button data-archiveproposal="${pr.id}" aria-label="${pr.status==='archived'?'恢复':'归档'}这条建议">${pr.status==='archived'?'恢复':'归档'}</button></div></div><details class="reason"><summary>修改原因与回复详情</summary><p>${esc(pr.reason)}</p><button data-reply="${pr.id}">查看本轮完整回复</button><p class="mini">样稿回复为预设示例。</p></details>`:''}</article>`}).join(''):`<div class="empty-chat"><h2>从一个想法，<br>开始这篇论文。</h2><p>先聊研究问题、提供材料，或让 Kimi 起草结构。<br>初稿出来后，在右边边读边改。</p><button class="suggestion" data-prompt="请根据我提供的材料，先写论文提纲和引言初稿，不编造文献或实验结果。">整理提纲并起草引言</button><button class="suggestion" data-prompt="先讨论论文的研究问题和结构，暂时不要写正文。">先讨论研究问题与结构</button></div>`;if(ui.busy)$('#messages').insertAdjacentHTML('beforeend','<div class="busy" role="status">正在演示生成过程 · 可以继续阅读和保存批注</div>')}
function composer(){const s=session();$('#composer').innerHTML=`${s.pending.length?`<details class="pending" open><summary>待发送批注 ${s.pending.length} · 将发到当前会话</summary>${s.pending.map((n,i)=>`<div class="pending-row"><span title="${esc(n.quote)}">${esc(n.note||n.quote)}</span><button data-remove="${i}" aria-label="移除第 ${i+1} 条批注">×</button></div>`).join('')}</details>`:''}<div class="compose-box"><textarea id="input" aria-label="给 Kimi 的消息" placeholder="输入要求，或将右侧批注加入这条会话…" ${s.archived?'disabled':''}>${esc(s.draft)}</textarea><div class="compose-tools"><button class="icon" data-action="attach" aria-label="添加项目文件">${icon('attach')}</button><select id="model" aria-label="Kimi 模型"><option>Kimi K3 256K</option></select><button id="send" class="send" aria-label="发送到当前会话" ${ui.busy||s.archived?'disabled':''}>${icon('arrow')}</button></div></div><div class="composer-note"><span>${ui.busy?'运行中，新批注会留在待发送列表':'同一会话继续 · ⌘ Enter 发送'}</span><span>示例内容与操作</span></div>`;$('#input').oninput=e=>{s.draft=e.target.value;save()};$('#input').onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();send()}};$('#send').onclick=send}
function paper(text,highlight=true){return `<article class="paper" id="paper-page"><h2>Collaborative Paper Revision</h2><div class="authors">Fictional manuscript · Interaction prototype</div><h3>Abstract</h3><p>This illustrative manuscript explores a workflow for writing and revising academic papers. It connects an ongoing conversation with a document preview, project resources, and version history. No experimental findings are reported.</p><h3>1 &nbsp; Introduction</h3><p>${highlight?'<mark>':''}${esc(text)}${highlight?'</mark>':''}</p><p>In this example, authors begin with an outline, develop a draft, and refine it through comments. The manuscript, bibliography, figures, and tables remain part of the same project.</p><h3>2 &nbsp; Methods</h3><p>Comments are collected in the active conversation. The author reviews the proposed document before accepting changes into the manuscript.</p><h3>3 &nbsp; Project resources</h3><p>Figure 1 illustrates the review workflow. Table 1 lists its stages. References are maintained in a separate bibliography file.</p><p>The example demonstrates interface behavior only. It does not describe a validated research method.</p><div class="page-number">1</div></article>`}
function renderDoc(){$('#selection-popup').hidden=true;const p=project(),pr=proposal();const text=ui.history?.text||(ui.doc==='preview'&&pr?pr.text:p.accepted);const isPaper=ui.file.endsWith('.tex');let content='';if(isPaper){content=text?paper(text,ui.doc==='preview'): `<div class="docempty"><div>${icon('file')}<h2>论文会出现在这里</h2><p>在左侧说明你想写什么。<br>初稿生成后，即可预览、划选和批注。</p></div></div>`}else if(ui.file.endsWith('.bib')){content='<div class="resource"><h2>参考文献</h2><p>references.bib · 示例文献库</p><table><tr><th>引用键</th><th>文献</th></tr><tr><td>example2026</td><td>Collaborative Revision — 虚构示例</td></tr></table><p>正式版显示项目中的真实条目与引用位置。</p></div>'}else if(ui.file.endsWith('.svg')){content='<div class="resource"><h2>Figure 1</h2><div class="flow"><div>起草</div>→<div>审阅</div>→<div>采纳</div></div><p>项目里的图片预览 · 示例素材</p></div>'}else{content='<div class="resource"><h2>Table 1</h2><table><tr><th>阶段</th><th>论文状态</th></tr><tr><td>起草与建议</td><td>待确认</td></tr><tr><td>审阅</td><td>保留正式稿</td></tr><tr><td>采纳</td><td>更新并保存版本</td></tr></table></div>'}$('#document').innerHTML=`<div class="docbar"><span class="doc-name">${icon('file')}${isPaper?'main.pdf':esc(ui.file.split('/').at(-1))}</span>${isPaper?`<div class="seg"><button data-doc="official" class="${ui.doc==='official'?'active':''}">正式稿</button><button data-doc="preview" class="${ui.doc==='preview'?'active':''}" ${!pr?'disabled':''}>修改预览</button></div>${p.proposals.length?`<select id="preview-version" aria-label="预览版本">${p.proposals.map((v,i)=>`<option value="${v.id}" ${v.id===ui.proposal?'selected':''}>第 ${i+1} 版${v.status==='adopted'?' · 已采纳':''}</option>`).join('')}</select>`:''}<button class="icon" data-action="compare" aria-label="放大比较修改前后">${icon('expand')}对比</button>`:''}</div><div class="doccanvas">${content}</div><div class="docfooter"><span>${ui.history?'历史版本 · '+esc(ui.history.title):ui.doc==='preview'&&pr?pr.status==='adopted'?'已采纳版本':'预览尚未写入':'当前正式稿'} · 示意排版</span><label><input type="checkbox" id="auto-translate" ${ui.autoTranslate?'checked':''}>划选翻译</label></div>`;$('#auto-translate').onchange=e=>ui.autoTranslate=e.target.checked;const sel=$('#preview-version');if(sel)sel.onchange=e=>{ui.proposal=e.target.value;ui.doc='preview';ui.history=null;renderDoc()}}
function render(){sidebar();renderMessages();composer();renderDoc();save()}
function scrollMessages(){requestAnimationFrame(()=>{$('#messages').scrollTop=$('#messages').scrollHeight})}
function send(){if(ui.busy||session().archived)return;const p=project(),s=session(),text=s.draft.trim(),notes=[...s.pending];if(!text&&!notes.length){$('#input').focus();return}s.messages.push({role:'user',text:text||notes.map(n=>n.note||'请修改这段').join('\n'),quotes:notes.map(n=>n.quote)});s.draft='';s.pending=[];ui.busy=true;renderMessages();composer();save();scrollMessages();setTimeout(()=>{const discussion=/暂时不要|先讨论/.test(text);if(discussion){s.messages.push({role:'assistant',text:'我们可以先确定研究问题、已有证据和目标读者，再安排引言、方法与结果的结构。\n\n这是对话流程示例，尚未调用 Kimi。'})}else{const draft=!p.accepted&&p.proposals.length===0;const pr={id:crypto.randomUUID(),title:draft?'论文初稿':notes.length>1?`${notes.length} 条批注的修改`:'引言修改',text:draft?original:/简洁|简短/.test(text)?concise:revised,base:p.accepted||'',status:'pending',session:s.id,reason:'延续当前会话的写作要求；保留示例性质，不新增文献或实验结论。'};p.proposals.push(pr);p.files=[...fileList];s.messages.push({role:'assistant',text:draft?'初稿预览已准备好，包含论文入口、章节、参考文献和素材目录。请在右侧检查，然后决定是否采纳。':'已按这条会话中的补充要求准备修改预览。正文仍保留原版本，采纳后再更新。',proposal:pr.id});ui.proposal=pr.id;ui.doc='preview';ui.file='main.tex';ui.history=null}ui.busy=false;render();scrollMessages()},900)}
function projectSwitch(){modal(`<h2>选择论文项目</h2><p>每个项目保留自己的文件和会话。</p>${db.projects.map(p=>`<button class="choice" data-project="${p.id}">${esc(p.name)}<small>${esc(p.path)} · ${p.sessions.length} 条会话</small></button>`).join('')}<hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h3>从新项目开始</h3><label for="project-name">项目名称</label><input id="project-name" type="text" placeholder="例如：我的新论文"><label for="project-path">项目目录（样稿中仅记录路径）</label><input id="project-path" type="text" placeholder="~/Papers/my-new-paper"><div class="notice">这里演示项目选择。正式 App 使用 macOS 文件夹选择器；本页不会读取或创建这个目录。</div><button class="primary" id="create-project">创建示例项目</button>`);$('#create-project').onclick=()=>{const name=$('#project-name').value.trim(),path=$('#project-path').value.trim();if(!name||!path){toast('请填写项目名称和示例目录');return}const s=newSession();const p={id:crypto.randomUUID(),name,path,accepted:'',files:[],sessions:[s],session:s.id,proposals:[],history:[]};db.projects.push(p);switchProject(p.id)}}
function switchProject(id){if(ui.busy){toast('请等待本轮演示完成再切换项目');return}db.active=id;const p=project();ui.proposal=p.proposals.at(-1)?.id;ui.doc=p.proposals.length?'preview':'official';ui.file='main.tex';ui.history=null;close();render()}
function preview(id){ui.proposal=id;ui.doc='preview';ui.file='main.tex';ui.history=null;renderDoc();sidebar()}
function adopt(id){const pr=project().proposals.find(p=>p.id===id);if(!pr||pr.status!=='pending')return;modal(`<h2>采纳${esc(pr.title)}？</h2><p>更新示例正式稿，并留下整个项目的版本记录。当前会话继续保留。</p><p class="mini">交互演示，不改真实文件。</p><button class="primary" id="confirm-adopt">确认采纳（演示）</button>`);$('#confirm-adopt').onclick=()=>{const p=project();p.accepted=pr.text;pr.status='adopted';p.history.unshift({title:pr.title,text:pr.text,time:'刚刚',files:[...p.files]});ui.doc='official';ui.history=null;close();render();toast('示例正式稿已更新，会话继续保留')}}
function chooseSession(id){if(ui.busy){toast('本轮演示正在运行，请稍后切换');return}project().session=id;ui.history=null;render();scrollMessages()}
function history(){const p=project();modal(`<h2>论文版本</h2><p>已采纳的项目版本，与对话中的未采纳建议分开。</p><div class="versions">${p.history.length?p.history.map((h,i)=>`<button data-history="${i}">${esc(h.title)}<small>${h.time} · ${h.files.length} 个项目文件</small></button>`).join(''):'<div class="notice">采纳第一份初稿后，这里会出现本地版本。</div>'}</div><p class="mini">查看版本时，左侧会话保持在原处。</p>`)}
function git(){const p=project();modal(`<h2>GitHub · 整个项目</h2><p>${esc(p.name)} · main</p><table><thead><tr><th>同步</th><th>文件</th></tr></thead><tbody>${p.files.map(f=>`<tr><td><input type="checkbox" class="git-file" aria-label="同步 ${esc(f)}" value="${esc(f)}" checked></td><td>${esc(f)}</td></tr>`).join('')}</tbody></table><p class="mini">排除编译缓存和私有设置；正式版会完整列出实际范围。</p><label for="git-note">版本说明</label><input type="text" id="git-note" placeholder="完善引言与相关素材"><div class="notice">手动同步不会替代本地版本。协作者有更新时，先比较；冲突时让你决定。</div><div class="actions"><button data-action="collaborator">查看协作者更新</button><button class="primary" id="git-review" ${p.files.length?'':'disabled'}>检查同步范围</button></div>`);$('#git-review').onclick=()=>{const list=[...document.querySelectorAll('.git-file:checked')].map(e=>e.value);if(!list.length){toast('请至少选择一个文件');return}modal(`<h2>确认同步范围</h2><p>${list.length} 个项目文件</p>${list.map(f=>`<p>${esc(f)}</p>`).join('')}<p class="mini">此演示不会连接 GitHub。</p><button class="primary" id="git-finish">完成同步演示</button>`);$('#git-finish').onclick=()=>{close();toast('流程演示结束，没有上传文件')}}}
function showSelection(text,rect){if(session().archived){toast('请先恢复会话，再加入批注');return}ui.selection=text;const pop=$('#selection-popup');pop.innerHTML=`<button class="icon" data-action="closeselection" style="float:right" aria-label="关闭翻译">×</button><h3>${ui.autoTranslate?'划选翻译':'添加批注'}</h3><p class="selected-quote">${esc(text)}</p>${ui.autoTranslate?'<p>学术写作需要反复调整论证、证据与表达。作者可以在采纳之前检查修改效果。</p><p class="mini">示例译文 · 正式版由 Qwen 翻译选中文字</p>':''}<label for="annotation" class="mini">告诉 Kimi 如何修改</label><textarea id="annotation" placeholder="例如：更简洁，保留关键含义"></textarea><div class="actions"><button id="save-annotation">加入待发送批注</button><button class="primary" id="send-annotation" ${ui.busy?'disabled':''}>发到当前会话</button></div>`;pop.hidden=false;pop.style.left=Math.max(12,Math.min(innerWidth-352,rect.left))+'px';pop.style.top=Math.max(12,Math.min(innerHeight-pop.offsetHeight-12,rect.bottom+10))+'px';function append(){session().pending.push({quote:text,note:$('#annotation').value.trim()});pop.hidden=true;composer();save()}$('#save-annotation').onclick=()=>{append();toast('已加入当前会话，可继续划选其他段落')};$('#send-annotation').onclick=()=>{append();send()}}
document.addEventListener('mouseup',e=>{if(!e.target.closest('#document .paper'))return;const sel=getSelection();if(!sel||sel.isCollapsed||!sel.rangeCount)return;const range=sel.getRangeAt(0);const article=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement;if(!article.closest('#document .paper'))return;const text=sel.toString().trim();if(text.length>3)showSelection(text.slice(0,4000),range.getBoundingClientRect())});
document.addEventListener('scroll',e=>{if(e.target.closest?.('.doccanvas'))$('#selection-popup').hidden=true},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#selection-popup').hidden=true});
const actions={close,files(){document.body.classList.toggle('hidden-nav');if(innerWidth<=850)document.body.classList.toggle('mobile-nav')},history,git,showpaper(){ui.file='main.tex';renderDoc()},archivesession(){if(ui.busy){toast('请先完成本轮演示');return}session().archived=!session().archived;render();toast(session().archived?'会话已归档，内容与论文保留':'会话已恢复')},newsession(){if(ui.busy)return;modal('<h2>新建会话</h2><p>新会话拥有独立对话历史；同一项目的文件保持可用。日常修改可以继续留在原会话。</p><label for="session-name">会话名称</label><input id="session-name" type="text" value="新的写作讨论"><button id="new-session-confirm" class="primary" style="margin-top:18px">创建会话</button>');$('#new-session-confirm').onclick=()=>{const s=newSession($('#session-name').value.trim()||'新的写作讨论');project().sessions.push(s);project().session=s.id;close();render()}},context(){modal(`<h2>这条会话的上下文</h2><p>项目：${esc(project().name)}</p><p>会话：${esc(session().title)} · ${session().messages.length} 条消息</p><p>项目文件：${project().files.length} 个</p><div class="notice">正式接入的目标：复用原生 Kimi 会话，连续接收要求、批注和采纳结果。长对话可能压缩，关键写作要求与采纳决定还需保存在项目记录中。</div><p class="mini">此样稿只保存浏览器中的示例消息，不表示已经接入原生会话或拥有无限上下文。</p>`)},attach(){modal(`<h2>将项目文件加入对话</h2>${project().files.map(f=>`<button class="choice" data-attach="${esc(f)}">${icon('file')} ${esc(f)}</button>`).join('')||'<p>新项目还没有文件。正式版可从本地选择参考材料。</p>'}<p class="mini">样稿仅将文件名添加到输入框，不读取文件内容。</p>`)},compare(){const pr=proposal();if(!pr){toast('还没有可比较的建议');return}modal(`<h2>${esc(pr.title)} · 修改前后</h2><p class="mini">放大审阅，关闭后回到原会话。示意排版，非真实 PDF。</p><div class="comparison"><div class="before"><h3 class="label">建议生成时的正文</h3>${pr.base?paper(pr.base):'<p>空白项目，尚无正文。</p>'}</div><div><h3 class="label">建议预览</h3>${paper(pr.text)}</div></div>`,true)},collaborator(){modal('<h2>协作者更新 · 演示</h2><p>协作者更新了 references.bib，本地修改位于 sections/introduction.tex。</p><div class="notice">正式版先比较远端与本地版本；如同一处发生冲突，展示双方内容，由你决定，不自动覆盖。</div>')},closeselection(){$('#selection-popup').hidden=true}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.action)actions[d.action]?.();if(d.project)switchProject(d.project);if(d.session)chooseSession(d.session);if(d.file){ui.file=d.file;ui.history=null;renderDoc();sidebar()}if(d.preview)preview(d.preview);if(d.adopt)adopt(d.adopt);if(d.doc){ui.doc=d.doc;ui.history=null;renderDoc()}if(d.prompt){session().draft=d.prompt;composer();save();$('#input').focus()}if(d.remove!==undefined){session().pending.splice(Number(d.remove),1);composer();save()}if(d.history!==undefined){ui.history=project().history[Number(d.history)];ui.doc='official';ui.file='main.tex';close();renderDoc()}if(d.attach){session().draft+=(session().draft?'\n':'')+'@'+d.attach+' ';close();composer();save();$('#input').focus()}if(d.reply){const pr=project().proposals.find(p=>p.id===d.reply);modal(`<h2>本轮完整回复 · 示例</h2><p>${esc(pr.reason)}</p><h3>建议文字</h3><p>${esc(pr.text)}</p><p class="mini">正式版原样保留模型返回内容；不把说明摘要当作完整回复。</p>`)}if(d.archiveproposal){const pr=project().proposals.find(p=>p.id===d.archiveproposal);if(pr.status==='archived')pr.status=pr.previousStatus||'pending';else{pr.previousStatus=pr.status;pr.status='archived'}renderMessages();save();toast('建议归档状态已更新，会话记录保留')}});
$('#sidebar-toggle').innerHTML=icon('panel');$('#sidebar-toggle').onclick=actions.files;$('#project-switch').onclick=projectSwitch;
let dragging=false;const divider=$('#divider');divider.onpointerdown=e=>{dragging=true;divider.setPointerCapture(e.pointerId)};divider.onpointerup=()=>dragging=false;function resize(percent){const n=Math.max(30,Math.min(65,percent));document.documentElement.style.setProperty('--fraction',String(n/100));divider.setAttribute('aria-valuenow',String(Math.round(n)))}divider.onpointermove=e=>{if(dragging){const side=$('#sidebar').getBoundingClientRect().width;resize((e.clientX-side)/(innerWidth-side-5)*100)}};divider.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();resize(Number(divider.getAttribute('aria-valuenow'))+(e.key==='ArrowLeft'?-2:2))}};
render();
